<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;

/**
 * Default production-safe application seed.
 *
 * Seeds required system configuration only. Model events remain enabled so UUID
 * primary keys are generated by Eloquent creating callbacks.
 *
 * Does **not** seed demo Owners, Companies, Branches, or operational transactions.
 * Opt-in local demo data: {@see LocalDemoWorkspaceSeeder}
 * (`php artisan db:seed --class=LocalDemoWorkspaceSeeder`) — never invoked here.
 *
 * Order matters: RBAC → geography → financial masters → TDS → subscription → Super Admin.
 */
class DatabaseSeeder extends Seeder
{
    /**
     * Seed the application's database.
     */
    public function run(): void
    {
        $this->call([
            RbacSeeder::class,
            IndiaGeographySeeder::class,
            PaymentModeSeeder::class,
            GstRateSeeder::class,
            TdsReferenceRulesSeeder::class,
            SubscriptionCatalogueSeeder::class,
            InternalSuperAdminSeeder::class,
        ]);
    }
}
